WITH ranked AS (SELECT id, customer_id, device, browser, started_at, country FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id, device ORDER BY started_at ASC, id ASC) AS rank_in_group FROM sessions) ranked WHERE rank_in_group = 1) SELECT s.id, s.customer_id, s.browser, s.started_at, s.country, CASE WHEN browser RLIKE '^(Safari|Firefox)$' THEN 'EXTENDED' ELSE 'CORE' END AS browser_zone, (SELECT MAX(s2.monthly_fee) FROM subscriptions s2 WHERE s2.customer_id = s.customer_id) AS max_subscription_monthly_fee FROM ranked s ORDER BY max_subscription_monthly_fee DESC;
